python3 - <<'EOF'
p='index.html'; s=open(p).read()
start=s.index('  var state;'); end=s.index('  clearAll();\n</script>')
new = r'''  var state;

  // [REQ-001] reset to the initial state: display 0, nothing pending
  // [REQ-003] clear also leaves the error state
  function clearAll() {
    state = { entry: '0', stored: null, op: null, fresh: true, typing: false, error: false };
    render();
  }

  // [REQ-001] apply an operator
  // [REQ-003] exact result, never rounded; division by zero returns null (error)
  function compute(a, op, b) {
    if (op === '+') return a + b;
    if (op === '-') return a - b;
    if (op === '*') return a * b;
    if (b === 0) return null;
    return a / b;
  }

  // [REQ-003] presentation only: at most 10 significant digits, no trailing zeros,
  // exponential only when |n| >= 1e10 or |n| < 1e-9
  function formatNumber(n) {
    if (n === 0) return '0';
    if (!isFinite(n)) return String(n);
    var parts = n.toExponential(9).split('e');
    var exp = Number(parts[1]);
    if (exp >= 10 || exp < -9) {
      return parts[0].replace(/\.?0+$/, '') + 'e' + (exp >= 0 ? '+' : '') + exp;
    }
    var sign = n < 0 ? '-' : '';
    var digits = parts[0].replace('-', '').replace('.', '');
    var intPart, fracPart;
    if (exp >= 0) {
      intPart = digits.slice(0, exp + 1);
      fracPart = digits.slice(exp + 1);
    } else {
      intPart = '0';
      fracPart = new Array(-exp).join('0') + digits;
    }
    fracPart = fracPart.replace(/0+$/, '');
    return sign + intPart + (fracPart ? '.' + fracPart : '');
  }

  // [REQ-003] enter the error state
  function setError() {
    state.error = true;
    render();
  }

  // [REQ-001] digits build the entry
  function inputDigit(d) {
    if (state.fresh) {
      state.entry = d;
      state.fresh = false;
    } else {
      state.entry = state.entry === '0' ? d : state.entry + d;
    }
    state.typing = true;
    render();
  }

  // [REQ-001] at most one decimal point per entry
  function inputDot() {
    if (state.fresh) {
      state.entry = '0.';
      state.fresh = false;
    } else if (state.entry.indexOf('.') === -1) {
      state.entry += '.';
    }
    state.typing = true;
    render();
  }

  // [REQ-001] store the operator; chains evaluate left to right
  // [REQ-002] immediate execution: an operator first applies the waiting op and shows the
  // running result; no precedence, so 2 + 3 × 4 = is 20
  function inputOp(op) {
    var current = Number(state.entry);
    if (state.op !== null && !state.fresh) {
      var result = compute(state.stored, state.op, current);
      if (result === null) return setError();
      state.entry = String(result);
      state.stored = result;
    } else if (state.op === null) {
      state.stored = current;
    }
    state.op = op;
    state.fresh = true;
    state.typing = false;
    render();
  }

  // [REQ-001] equals shows the result of stored op entry
  function equals() {
    if (state.op === null) return;
    var result = compute(state.stored, state.op, Number(state.entry));
    if (result === null) return setError();
    state.entry = String(result);
    state.stored = null;
    state.op = null;
    state.fresh = true;
    state.typing = false;
    render();
  }

  // [REQ-001] data-value holds String(value)
  // [REQ-003] typed entry shown as typed; other numbers formatted at render time only;
  // data-value stays exact; data-error always present
  function render() {
    var value = Number(state.entry);
    if (state.error) {
      displayEl.textContent = 'Error';
      displayEl.setAttribute('data-value', 'NaN');
    } else {
      displayEl.textContent = state.typing ? state.entry : formatNumber(value);
      displayEl.setAttribute('data-value', String(value));
    }
    displayEl.setAttribute('data-error', state.error ? 'true' : 'false');
  }

  document.querySelector('.keys').addEventListener('click', function (e) {
    var btn = e.target.closest('button');
    if (!btn) return;
    var id = btn.getAttribute('data-testid');
    // [REQ-003] in the error state only clear works
    if (state.error && id !== 'key-clear') return;
    if (btn.hasAttribute('data-digit')) inputDigit(btn.getAttribute('data-digit'));
    else if (btn.hasAttribute('data-op')) inputOp(btn.getAttribute('data-op'));
    else if (id === 'key-dot') inputDot();
    else if (id === 'key-equals') equals();
    else if (id === 'key-clear') clearAll();
  });

'''
s=s[:start]+new+s[end:]
s=s.replace('data-value="0">0</div>','data-value="0" data-error="false">0</div>')
open(p,'w').write(s)
EOF
